export type ServiceVillePage = typeof seoPages[keyof typeof seoPages];

// Fonction pour obtenir les données d'une page par slug
export function getPageData(slug: string): ServiceVillePage | null {
  const key = slug as keyof typeof seoPages;
  return seoPages[key] || null;
}

export function getAllPages() {
  return Object.entries(seoPages).map(([slug, data]) => ({
    slug,
    ...data
  }));
}

